"""
Screen 3 — GPU passthrough (optional).
Shows detected discrete GPUs with an opt-in toggle.
Sub-options (Steam, Lutris, Looking Glass) appear when GPU passthrough is enabled.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw

from .base import BasePage
from ..state import WizardState, GPUDevice
from typing import Callable


class GPUScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="GPU Passthrough", tag="gpu")

    def _build(self):
        self._body.append(
            self.make_page_header(
                "GPU passthrough",
                "Optionally dedicate a discrete GPU to a gaming VM. "
                "This is entirely optional — privacy-focused users can skip this.",
            )
        )

        # GPU selection group
        self._gpu_group = Adw.PreferencesGroup()
        self._gpu_group.set_title("Detected discrete GPUs")
        self._body.append(self._gpu_group)

        self._no_gpu_label = Gtk.Label(label="No discrete GPUs detected.")
        self._no_gpu_label.add_css_class("dim-label")
        self._no_gpu_label.set_visible(False)
        self._body.append(self._no_gpu_label)

        # Options group — revealed when a GPU is selected
        self._options_group = Adw.PreferencesGroup()
        self._options_group.set_title("Gaming VM options")
        self._options_group.set_visible(False)
        self._body.append(self._options_group)

        # Steam toggle
        self._steam_row = Adw.SwitchRow()
        self._steam_row.set_title("Install Steam")
        self._steam_row.set_subtitle("Flatpak — for launching games from the host")
        self._steam_row.connect("notify::active", self._on_steam_toggled)
        self._options_group.add(self._steam_row)

        # Lutris toggle
        self._lutris_row = Adw.SwitchRow()
        self._lutris_row.set_title("Install Lutris")
        self._lutris_row.set_subtitle("Flatpak — open-source game manager")
        self._lutris_row.connect("notify::active", self._on_lutris_toggled)
        self._options_group.add(self._lutris_row)

        # Looking Glass toggle
        self._lg_row = Adw.SwitchRow()
        self._lg_row.set_title("Install Looking Glass")
        self._lg_row.set_subtitle("Low-latency display capture from the gaming VM")
        self._lg_row.set_active(True)  # Recommended default when GPU PT is on
        self._lg_row.connect("notify::active", self._on_lg_toggled)
        self._options_group.add(self._lg_row)

        # Contamination warning
        self._contam_banner = Adw.Banner()
        self._contam_banner.set_title(
            "This GPU shares an IOMMU group with other devices. "
            "Passthrough requires an ACS override kernel patch which may reduce "
            "security guarantees. Proceed only if you understand the trade-off."
        )
        self._contam_banner.set_revealed(False)
        self._body.append(self._contam_banner)

        self._btn_row = self.make_button_row(
            back_label="Back",
            back_cb=lambda: self.go_to("back"),
            next_label="Continue",
            next_cb=lambda: self.go_to("appvms"),
        )
        self._body.append(self._btn_row)

    def on_enter(self):
        # Clear GPU rows
        child = self._gpu_group.get_first_child()
        while child:
            nxt = child.get_next_sibling()
            self._gpu_group.remove(child)
            child = nxt

        gpus = self.state.gpus
        if not gpus:
            self._no_gpu_label.set_visible(True)
            self._gpu_group.set_visible(False)
            return

        # Radio-button group so only one GPU can be selected
        first_radio: Gtk.CheckButton | None = None

        for gpu in gpus:
            row = self._make_gpu_row(gpu, first_radio)
            self._gpu_group.add(row)
            if first_radio is None:
                first_radio = row.get_activatable_widget()

    def _make_gpu_row(self, gpu: GPUDevice, group_leader: "Gtk.CheckButton | None") -> Adw.ActionRow:
        row = Adw.ActionRow()
        row.set_title(gpu.description)
        group_label = "Isolated IOMMU group" if gpu.group_isolated else "Shared IOMMU group — see warning below"
        row.set_subtitle(
            f"IOMMU group {gpu.iommu_group}  ·  {gpu.pci_address}  ·  {group_label}"
        )

        radio = Gtk.CheckButton()
        if group_leader:
            radio.set_group(group_leader)
        radio.connect("toggled", self._on_gpu_toggled, gpu)
        row.add_prefix(radio)
        row.set_activatable_widget(radio)
        row.set_activatable(True)

        return row

    def _on_gpu_toggled(self, radio: Gtk.CheckButton, gpu: GPUDevice):
        if radio.get_active():
            self.state.gpu_passthrough = True
            self.state.selected_gpu = gpu
            self._options_group.set_visible(True)
            self._contam_banner.set_revealed(not gpu.group_isolated)
            # Sync Looking Glass default
            self.state.install_looking_glass = self._lg_row.get_active()
        else:
            # Another radio was selected; this one being deactivated
            if self.state.selected_gpu is gpu:
                self.state.gpu_passthrough = False
                self.state.selected_gpu = None
                self._options_group.set_visible(False)
                self._contam_banner.set_revealed(False)

    def _on_steam_toggled(self, row, _param):
        self.state.install_steam = row.get_active()

    def _on_lutris_toggled(self, row, _param):
        self.state.install_lutris = row.get_active()

    def _on_lg_toggled(self, row, _param):
        self.state.install_looking_glass = row.get_active()
